// Returns the free class-heritage abilities for a native class + subrace combo.
// Returns [] for non-native combinations (hard race-lock => no free abilities).
export function getClassRacialTraits(className, raceId, subraceId) {
  const base = resolveClassHeritageName(className);
  if (!base || !CLASS_RACIALS[base]) return [];
  const heritageId = resolveClassHeritageId(raceId, subraceId);
  if (!heritageId) return [];
  return CLASS_RACIALS[base][heritageId] ? [...CLASS_RACIALS[base][heritageId]] : [];
}
